import RPC from 'discord-rpc';

// NOTE: The 'icon512' image key must be uploaded to Discord Developer Portal
// at https://discord.com/developers/applications/{clientId}/rich-presence/assets
// The image should be a 512x512 PNG of your app icon

export interface DiscordPresenceConfig {
  clientId: string;
  appName: string;
  appVersion: string;
  appDeveloper: string;
  largeImageKey: string;
  websiteUrl: string;
  developerUrl: string;
}

export interface DiscordPresenceData {
  style: string;
  halftoneMode?: 'grayscale' | 'cmyk';
  mediaType?: 'image' | 'video';
  effectsCount?: number;
  isExporting?: boolean;
  videoProgress?: { current: number; total: number };
}

export class DiscordPresence {
  private client: RPC.Client | null = null;
  private startTimestamp: number | null = null;
  private presenceData: DiscordPresenceData | null = null;
  private isConnected: boolean = false;
  private config: DiscordPresenceConfig;

  constructor(config: DiscordPresenceConfig) {
    this.config = config;
    this.initialize();
  }

  private async initialize() {
    try {
      this.client = new RPC.Client({ transport: 'ipc' });
      
      this.client.on('ready', () => {
        this.isConnected = true;
        
        // Set initial presence if we have state
        if (this.presenceData) {
          this.update();
        }
      });

      await this.client.login({ clientId: this.config.clientId });
    } catch (error) {
      // Silently fail if Discord is not running
      this.client = null;
      this.isConnected = false;
    }
  }

  /**
   * Start tracking presence with rich data
   */
  public start(data: DiscordPresenceData | string) {
    if (!this.client || !this.isConnected) {
      return;
    }

    this.startTimestamp = Math.floor(Date.now() / 1000);
    
    if (typeof data === 'string') {
      this.presenceData = { style: data };
    } else {
      this.presenceData = data;
    }
    
    this.update();
  }

  /**
   * Update presence data while keeping the same session
   * If no session exists, automatically starts a new one
   */
  public updatePresence(data: DiscordPresenceData | string) {
    if (!this.client || !this.isConnected) {
      return;
    }

    if (this.startTimestamp === null) {
      this.start(data);
      return;
    }

    if (typeof data === 'string') {
      this.presenceData = { style: data };
    } else {
      this.presenceData = data;
    }
    
    this.update();
  }

  /**
   * Legacy method for backward compatibility
   */
  public updateStyle(style: string) {
    this.updatePresence(style);
  }

  /**
   * Update Discord presence
   */
  private async update() {
    if (!this.client || !this.isConnected) {
      return;
    }

    if (!this.presenceData) {
      return;
    }

    const { style, halftoneMode, mediaType, effectsCount, isExporting, videoProgress } = this.presenceData;

    // Build details line
    const isHalftone = style === 'Halftone';
    let details: string;
    if (isHalftone && halftoneMode) {
      const modeLabel = halftoneMode === 'cmyk' ? 'CMYK' : 'Grayscale';
      details = `Halftoning: ${modeLabel}`;
    } else if (isHalftone) {
      details = 'Halftoning';
    } else {
      details = `Dithering: ${style}`;
    }

    // Build state line
    let state = '';
    const stateParts: string[] = [];

    if (isExporting) {
      stateParts.push('Exporting');
    } else if (mediaType) {
      const mediaTypeLabel = mediaType === 'video' ? 'Video' : 'Image';
      stateParts.push(mediaTypeLabel);
    }

    if (effectsCount && effectsCount > 0) {
      stateParts.push(`${effectsCount} effect${effectsCount > 1 ? 's' : ''}`);
    }

    // Always include version number
    if (stateParts.length > 0) {
      stateParts.push(`v${this.config.appVersion}`);
    }
    
    state = stateParts.join(' | ') || `Version ${this.config.appVersion}`;

    const activity: RPC.Presence = {
      details,
      state,
      startTimestamp: this.startTimestamp || undefined,
      largeImageKey: this.config.largeImageKey,
      largeImageText: this.config.appName,
      buttons: [
        { label: this.config.appName, url: this.config.websiteUrl },
        { label: `By ${this.config.appDeveloper}`, url: this.config.developerUrl },
      ],
    };

    // Add video/animation progress if available
    if (videoProgress && videoProgress.total > 0) {
      activity.partySize = videoProgress.current;
      activity.partyMax = videoProgress.total;
    }

    try {
      await this.client.setActivity(activity);
    } catch (error) {
      // Silently fail
    }
  }

  /**
   * Clear presence (called when dithering stops or app closes)
   */
  public async clear() {
    if (!this.client || !this.isConnected) {
      return;
    }

    try {
      await this.client.clearActivity();
      this.startTimestamp = null;
      this.presenceData = null;
    } catch (error) {
      // Silently fail
    }
  }

  /**
   * Disconnect and cleanup
   */
  public async destroy() {
    if (this.client) {
      try {
        await this.clear();
        await this.client.destroy();
      } catch (error) {
        // Silently fail
      }
      
      this.client = null;
      this.isConnected = false;
    }
  }
}
