// Load license manager from bytecode
let licenseManager: any = null;

// Load halftone processor from bytecode
let halftoneProcessor: any = null;

function loadLicenseManager(): void {
  try {
    logEarlyCrash('[License] Starting to load license manager...', '');
    
    // In development, use the source file directly
    // Use dynamic require to prevent bundling by esbuild
    if (!app.isPackaged) {
      logEarlyCrash('[License] Loading in dev mode...', '');
      const licensePath = path.join(__dirname, '..', 'electron', 'license-bundle.cjs');
      const { licenseManager: lm } = require(licensePath);
      licenseManager = lm;
      licenseManager.setPackaged(false);
      console.log('[License] Loaded from source (dev mode)');
      logEarlyCrash('[License] Loaded successfully (dev mode)', '');
      return;
    }

    // In production, load from bytecode
    logEarlyCrash('[License] Loading in production mode...', '');
    
    // When files are unpacked from ASAR, they're in app.asar.unpacked
    const basePath = __dirname.replace('app.asar', 'app.asar.unpacked');
    const manifestPath = path.join(basePath, 'license-manifest.json');
    
    if (!fs.existsSync(manifestPath)) {
      const error = 'License manifest not found';
      logEarlyCrash('[License] ERROR:', error);
      throw new Error(error);
    }

    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    const jscPath = path.join(basePath, manifest.file);
    
    if (!fs.existsSync(jscPath)) {
      const error = 'License bytecode not found';
      logEarlyCrash('[License] ERROR:', error);
      throw new Error(error);
    }

    // Load bytenode from unpacked directory (can't load native modules from ASAR)
    logEarlyCrash('[License] Loading bytenode...', '');
    // basePath is app.asar.unpacked/dist, but node_modules is at app.asar.unpacked/node_modules
    const unpackedRoot = basePath.replace(/[\\\/]dist$/, '');
    const bytenodePath = path.join(unpackedRoot, 'node_modules', 'bytenode');
    
    try {
      require(bytenodePath);
      logEarlyCrash('[License] Bytenode loaded', '');
    } catch (bytenodeErr) {
      logEarlyCrash('[License] Bytenode load failed', bytenodeErr);
      throw bytenodeErr;
    }
    
    const { licenseManager: lm } = require(jscPath);
    
    logEarlyCrash('[License] Bytecode loaded successfully', '');
    logEarlyCrash('[License] Setting up license manager...', '');
    licenseManager = lm;
    licenseManager.setPackaged(true);
    
    console.log('[License] Loaded from bytecode (production)');
    logEarlyCrash('[License] Loaded successfully (production)', '');
  } catch (error) {
    logEarlyCrash('[License] FAILED to load license manager', error);
    console.error('[License] Failed to load license manager:', error);
    throw error;
  }
}

function loadHalftoneProcessor(): void {
  try {
    if (!app.isPackaged) {
      return;
    }

    const basePath = __dirname.replace('app.asar', 'app.asar.unpacked');
    const manifestPath = path.join(basePath, 'halftone-manifest.json');
    
    if (!fs.existsSync(manifestPath)) {
      console.error('[Halftone] Manifest not found');
      return;
    }

    const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
    const jscPath = path.join(basePath, manifest.file);
    
    if (!fs.existsSync(jscPath)) {
      console.error('[Halftone] Bytecode not found');
      return;
    }

    const unpackedRoot = basePath.replace(/[\\\/]dist$/, '');
    const bytenodePath = path.join(unpackedRoot, 'node_modules', 'bytenode');
    require(bytenodePath);
    
    const module = require(jscPath);
    halftoneProcessor = module.processHalftone;
    
    console.log('[Halftone] Loaded from bytecode (production)');
  } catch (error) {
    console.error('[Halftone] Failed to load:', error);
  }
}

// Session log file (production only) - same base path as legacy palettes, logs subfolder
// Windows: %LOCALAPPDATA%\Studio AAA\Dither Boy\logs
// macOS: ~/Library/Application Support/Dither Boy/logs
function getAppDataDir(): string | null {
  if (process.platform === 'win32') {
    const localAppData = process.env.LOCALAPPDATA;
    if (!localAppData) return null;
    return path.join(localAppData, 'Studio AAA', 'Dither Boy');
  }
  if (process.platform === 'darwin') {
    return path.join(os.homedir(), 'Library', 'Application Support', 'Dither Boy');
  }
  return null;
}

function getLogsDir(): string | null {
  const base = getAppDataDir();
  if (!base) return null;
  return path.join(base, 'logs');
}

// License manager handles all validation in main process (secure)

let logStream: fs.WriteStream | null = null;

function initSessionLog(): void {
  if (!app.isPackaged) return;
  const dir = getLogsDir();
  if (!dir) return;
  try {
    fs.mkdirSync(dir, { recursive: true });
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const logPath = path.join(dir, `session-${timestamp}.log`);
    logStream = fs.createWriteStream(logPath, { flags: 'a' });
    const originalConsole = { log: console.log, warn: console.warn, error: console.error };
    const write = (level: string, ...args: unknown[]) => {
      try {
        const msg = args.map(a => {
          try {
            return typeof a === 'object' ? JSON.stringify(a) : String(a);
          } catch {
            return String(a);
          }
        }).join(' ');
        const line = `[${new Date().toISOString()}] [${level}] [main] ${msg}\n`;
        logStream?.write(line);
      } catch {
        // ignore
      }
      (originalConsole as Record<string, (...a: unknown[]) => void>)[level === 'log' ? 'log' : level === 'warn' ? 'warn' : 'error'](...args);
    };
    console.log = (...a: unknown[]) => write('log', ...a);
    console.warn = (...a: unknown[]) => write('warn', ...a);
    console.error = (...a: unknown[]) => write('error', ...a);
  } catch (err) {
    console.error('Failed to init session log:', err);
  }
}

function writeToSessionLog(level: string, ...args: unknown[]): void {
  if (!logStream) return;
  try {
    const msg = args.map(a => {
      try {
        return typeof a === 'object' ? JSON.stringify(a) : String(a);
      } catch {
        return String(a);
      }
    }).join(' ');
    const line = `[${new Date().toISOString()}] [${level}] [renderer] ${msg}\n`;
    logStream.write(line);
  } catch {
    // ignore
  }
}

let discordPresence: DiscordPresence | null = null;

let pendingClose = false;

function handleRendererProcessGone(window: BrowserWindow, details: Electron.RenderProcessGoneDetails): void {
  console.error('[Renderer] render-process-gone', details);
  logEarlyCrash('[Renderer] render-process-gone', details);

  const reason = details.reason === 'oom'
    ? 'The editor ran out of memory while processing media.'
    : `The renderer process exited unexpectedly (${details.reason}).`;

  dialog.showErrorBox(
    'Renderer Crashed',
    `${reason}\n\nThe current window will close so the app does not remain in a broken state.`,
  );

  pendingClose = true;
  if (!window.isDestroyed()) {
    window.destroy();
  }
}

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 1000,
    minHeight: 600,
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true,
      preload: path.join(__dirname, 'preload.js'),
      // Disable DevTools in production builds
      devTools: !app.isPackaged,
    },
    frame: true,
    titleBarStyle: 'default',
    backgroundColor: '#1a1a1a',
    // Enable smoother fullscreen transitions
    simpleFullscreen: false, // Use native fullscreen on macOS for best experience
    fullscreenable: true,
  });

  // Remove default menu in production
  if (app.isPackaged) {
    if (process.platform === 'darwin') {
      // On macOS, we need to provide a minimal menu (can't just remove it entirely)
      // Only include the app menu with quit option, no View/Developer menu
      const template: Electron.MenuItemConstructorOptions[] = [
        {
          label: app.name,
          submenu: [
            { role: 'about' },
            { type: 'separator' },
            { role: 'hide' },
            { role: 'hideOthers' },
            { role: 'unhide' },
            { type: 'separator' },
            { role: 'quit' }
          ]
        },
        {
          label: 'Edit',
          submenu: [
            { role: 'undo' },
            { role: 'redo' },
            { type: 'separator' },
            { role: 'cut' },
            { role: 'copy' },
            { role: 'paste' },
            { role: 'selectAll' }
          ]
        },
        {
          label: 'Window',
          submenu: [
            { role: 'minimize' },
            { role: 'zoom' },
            { type: 'separator' },
            { role: 'front' }
          ]
        }
      ];
      Menu.setApplicationMenu(Menu.buildFromTemplate(template));
    } else {
      // On Windows/Linux, completely remove the menu
      Menu.setApplicationMenu(null);
    }
  }

  // Handle window close event
  mainWindow.on('close', (e) => {
    if (pendingClose) {
      // User confirmed close, allow it
      pendingClose = false;
      return; // Allow close to proceed
    }

    // Prevent close and ask renderer
    e.preventDefault();
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('close-requested');
    }
  });

  // Disable right-click context menu in production (prevents DevTools access)
  if (app.isPackaged) {
    mainWindow.webContents.on('context-menu', (e) => {
      e.preventDefault();
    });
  }

  // Block new windows (app uses modals only)
  mainWindow.webContents.setWindowOpenHandler(() => ({ action: 'deny' }));

  mainWindow.webContents.on('render-process-gone', (_event, details) => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      handleRendererProcessGone(mainWindow, details);
    }
  });

  // Load the app
  if (!app.isPackaged) {
    // Read port from environment variable or use default
    const port = process.env.VITE_PORT || '5173';
    const devUrl = `http://localhost:${port}`;
    mainWindow.loadURL(devUrl);
    mainWindow.webContents.openDevTools();
  } else {
    // In production, main.js is in dist/, renderer is in dist/renderer/
    mainWindow.loadFile(path.join(__dirname, 'renderer', 'index.html'));
  }

  mainWindow.on('closed', () => {
    mainWindow = null;
    pendingClose = false;
  });

  // Listen for fullscreen state changes and notify renderer
  mainWindow.on('enter-full-screen', () => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('fullscreen-changed', true);
    }
  });
  
  mainWindow.on('leave-full-screen', () => {
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send('fullscreen-changed', false);
    }
  });
}

// Register IPC handlers for close confirmation (outside createWindow)
ipcMain.on('allow-close', () => {
  if (mainWindow && !mainWindow.isDestroyed()) {
    // Use destroy() to forcefully close the window
    mainWindow.destroy();
  }
});

ipcMain.on('cancel-close', () => {
  pendingClose = false;
});

