// IPC handler for open dialog
ipcMain.handle('dialog:openDialog', async (event, options: {
  properties?: ('openFile' | 'openDirectory' | 'multiSelections' | 'showHiddenFiles')[];
  title?: string;
  defaultPath?: string;
  filters?: { name: string; extensions: string[] }[];
}) => {
  if (!mainWindow) {
    return { canceled: true, filePaths: [] };
  }

  const result = await dialog.showOpenDialog(mainWindow, {
    properties: options.properties || ['openDirectory'],
    title: options.title,
    defaultPath: options.defaultPath,
    filters: options.filters,
  });

  return result;
});

// IPC handler for save dialog
ipcMain.handle('show-save-dialog', async (event, options: {
  defaultPath?: string;
  filters?: { name: string; extensions: string[] }[];
}) => {
  if (!mainWindow) {
    return { canceled: true };
  }

  const result = await dialog.showSaveDialog(mainWindow, {
    defaultPath: options.defaultPath || 'exported-image.png',
    filters: options.filters || [
      { name: 'PNG Image', extensions: ['png'] },
      { name: 'JPEG Image', extensions: ['jpg', 'jpeg'] },
      { name: 'WebP Image', extensions: ['webp'] },
      { name: 'MP4 Video', extensions: ['mp4'] },
      { name: 'WebM Video', extensions: ['webm'] },
      { name: 'All Files', extensions: ['*'] }
    ]
  });

  return result;
});

// IPC handler for writing file
ipcMain.handle('write-file', async (event, filePath: string, dataUrl: string) => {
  try {
    // Extract base64 data from data URL
    const matches = dataUrl.match(/^data:([A-Za-z-+\/]+);base64,(.+)$/);
    if (!matches || matches.length !== 3) {
      throw new Error('Invalid data URL format');
    }

    const base64Data = matches[2];
    const buffer = Buffer.from(base64Data, 'base64');

    // Write file
    fs.writeFileSync(filePath, buffer);

    return { success: true };
  } catch (error) {
    console.error('Error writing file:', error);
    return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
  }
});

// IPC handler for writing binary file (for video blobs)
ipcMain.handle('write-file-binary', async (event, filePath: string, arrayBuffer: ArrayBuffer) => {
  try {
    if (!arrayBuffer || arrayBuffer.byteLength === 0) {
      return { success: false, error: 'Refusing to write empty file: export produced 0 bytes' };
    }
    const buffer = Buffer.from(arrayBuffer);
    fs.writeFileSync(filePath, buffer);
    return { success: true };
  } catch (error) {
    console.error('Error writing binary file:', error);
    return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
  }
});

// IPC handler for reading file
ipcMain.handle('read-file', async (event, filePath: string) => {
  try {
    const buffer = await fs.promises.readFile(filePath);
    return { success: true, data: buffer };
  } catch (error) {
    console.error('Error reading file:', error);
    return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
  }
});

// IPC handler for reading directory contents
ipcMain.handle('read-directory', async (event, dirPath: string) => {
  try {
    const files = fs.readdirSync(dirPath);
    // Return only files, not directories
    return files.filter(file => {
      const fullPath = path.join(dirPath, file);
      return fs.statSync(fullPath).isFile();
    });
  } catch (error) {
    console.error('Error reading directory:', error);
    return [];
  }
});

// IPC handler for creating a directory (recursive)
ipcMain.handle('create-directory', async (event, dirPath: string) => {
  try {
    fs.mkdirSync(dirPath, { recursive: true });
    return { success: true };
  } catch (error) {
    console.error('Error creating directory:', error);
    return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
  }
});

// Read licenses file from the app resources
ipcMain.handle('read-licenses-file', async () => {
  try {
    // In production, LICENSES.txt is in dist/renderer/LICENSES.txt
    // In dev mode, it's served by Vite from public/LICENSES.txt
    let licensePath: string;
    
    if (app.isPackaged) {
      // Production: Look in the resources directory
      licensePath = path.join(process.resourcesPath, 'app.asar', 'dist', 'renderer', 'LICENSES.txt');
      
      // If not found in asar, try unpackaged resources
      if (!fs.existsSync(licensePath)) {
        licensePath = path.join(process.resourcesPath, 'app', 'dist', 'renderer', 'LICENSES.txt');
      }
    } else {
      // Development: Look in public folder or dist/renderer
      licensePath = path.join(__dirname, '..', 'public', 'LICENSES.txt');
      
      if (!fs.existsSync(licensePath)) {
        licensePath = path.join(__dirname, '..', 'dist', 'renderer', 'LICENSES.txt');
      }
    }
    
    if (!fs.existsSync(licensePath)) {
      console.error('LICENSES.txt not found at:', licensePath);
      return { success: false, error: 'Licenses file not found' };
    }
    
    const content = fs.readFileSync(licensePath, 'utf-8');
    return { success: true, content };
  } catch (err) {
    console.error('Error reading licenses file:', err);
    return { success: false, error: (err as Error).message };
  }
});

// Dither bytecode worker (runs in separate thread to avoid blocking main process)
let ditherWorker: Worker | null = null;
const ditherPending = new Map<string, { resolve: (r: { width: number; height: number; buffer: ArrayBuffer }) => void; reject: (e: Error) => void }>();

/** Unpacked dir: worker script must be unpacked (Worker can't load from asar). */
function getDitherBaseDir(): string {
  if (!app.isPackaged) return __dirname;
  return __dirname.replace('app.asar', 'app.asar.unpacked');
}

/** Try asar first (fewer unpacked files), fall back to unpacked. */
function getDitherJscPath(): string | null {
  const candidates = app.isPackaged
    ? [__dirname, getDitherBaseDir()]
    : [__dirname];
  for (const baseDir of candidates) {
    const manifestPath = path.join(baseDir, 'bytecode-manifest.json');
    if (!fs.existsSync(manifestPath)) continue;
    try {
      const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8')) as { m?: string };
      const chunkName = manifest?.m;
      if (!chunkName || !chunkName.endsWith('.jsc')) continue;
      const jscPath = path.join(baseDir, chunkName);
      if (!fs.existsSync(jscPath)) continue;
      return jscPath;
    } catch {
      continue;
    }
  }
  return null;
}

function getDitherWorker(): Worker | null {
  if (ditherWorker) return ditherWorker;
  const jscPath = getDitherJscPath();
  if (!jscPath) {
    console.error('[Dither Worker] JSC path not found');
    return null;
  }
  try {
    const baseDir = getDitherBaseDir();
    const workerPath = path.join(baseDir, 'dither-worker-loader.cjs');
    
    if (!fs.existsSync(workerPath)) {
      console.error('[Dither Worker] Worker loader file does not exist');
      return null;
    }
    
    if (!fs.existsSync(jscPath)) {
      console.error('[Dither Worker] JSC file does not exist');
      return null;
    }
    
    ditherWorker = new Worker(workerPath, { workerData: { jscPath, isPackaged: app.isPackaged } });
    ditherWorker.on('message', (msg: { requestId?: string; result?: { width: number; height: number; buffer: ArrayBuffer }; error?: string }) => {
      const p = msg.requestId ? ditherPending.get(msg.requestId) : undefined;
      if (p) {
        ditherPending.delete(msg.requestId!);
        if (msg.error) {
          console.error('[Dither Worker] Worker reported error:', msg.error);
          p.reject(new Error(msg.error));
        } else if (msg.result) {
          p.resolve(msg.result);
        } else {
          p.reject(new Error('Invalid worker response'));
        }
      }
    });
    ditherWorker.on('error', (err) => {
      console.error('[Dither Worker] Worker error:', err);
      console.error('[Dither Worker] Error details:', {
        message: err.message,
        code: (err as any).code,
        stack: err.stack,
        requireStack: (err as any).requireStack,
      });
      for (const p of ditherPending.values()) p.reject(err);
      ditherPending.clear();
      ditherWorker = null;
    });
    
    console.log('[Dither Worker] Worker initialized successfully');
    return ditherWorker;
  } catch (err) {
    console.error('[Dither Worker] Failed to start:', err);
    console.error('[Dither Worker] Error details:', {
      message: err instanceof Error ? err.message : String(err),
      code: (err as any)?.code,
      stack: err instanceof Error ? err.stack : undefined,
    });
    return null;
  }
}

// IPC handler for dither processing (delegates to worker thread - bytecode, non-blocking)
// License check enforced in main process - renderer cannot bypass
ipcMain.handle('dither:process', async (_event, payload: {
  algorithmId: string;
  width: number;
  height: number;
  buffer: ArrayBuffer;
  params: { palette: string[]; orderedCycling?: boolean; scale: number; luminanceThreshold?: number; controls: Record<string, unknown> };
}) => {
  if (!licenseManager.isLicensed()) {
    throw new Error('License required');
  }
  const worker = getDitherWorker();
  if (!worker) {
    throw new Error('Dither bytecode not available');
  }
  const requestId = crypto.randomUUID();
  return new Promise<{ width: number; height: number; buffer: ArrayBuffer }>((resolve, reject) => {
    ditherPending.set(requestId, { resolve, reject });
    worker.postMessage({ requestId, payload }, [payload.buffer]);
  });
});

