// Legacy palette paths used by the Python app (appdirs user_data_dir)
// Windows: %LOCALAPPDATA%\Studio AAA\Dither Boy\palettes
// macOS: ~/Library/Application Support/Dither Boy/palettes
function getLegacyPaletteDir(): string | null {
  if (process.platform === 'win32') {
    const localAppData = process.env.LOCALAPPDATA;
    if (!localAppData) return null;
    return path.join(localAppData, 'Studio AAA', 'Dither Boy', 'palettes');
  }
  if (process.platform === 'darwin') {
    return path.join(os.homedir(), 'Library', 'Application Support', 'Dither Boy', 'palettes');
  }
  return null;
}

interface PaletteColor {
  r: number;
  g: number;
  b: number;
  percentage?: number;
}

interface PaletteData {
  category: string;
  name: string;
  color_count: number;
  colors: PaletteColor[];
}

interface ProcessedPalette {
  category: string;
  name: string;
  id: string;
  colorCount: number;
  hexColors: string[];
}

function rgbToHex(r: number, g: number, b: number): string {
  const toHex = (n: number) => {
    const hex = Math.max(0, Math.min(255, n)).toString(16);
    return hex.length === 1 ? '0' + hex : hex;
  };
  return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

const DEFAULT_CATEGORY = 'Uncategorized';

function processPaletteData(data: PaletteData): ProcessedPalette {
  const hexColors = data.colors.map(c => rgbToHex(c.r, c.g, c.b));
  const category = (data.category ?? '').toString().trim() || DEFAULT_CATEGORY;
  const name = (data.name ?? '').toString().trim() || 'Unnamed';
  const id = `${category.toLowerCase().replace(/\s+/g, '-')}-${name.toLowerCase().replace(/\s+/g, '-')}`;
  return {
    category,
    name,
    id,
    colorCount: data.color_count,
    hexColors,
  };
}

function isValidPaletteData(data: unknown): data is PaletteData {
  if (!data || typeof data !== 'object') return false;
  const d = data as Record<string, unknown>;
  if (d.category !== undefined && d.category !== null && typeof d.category !== 'string') return false;
  if (d.name !== undefined && d.name !== null && typeof d.name !== 'string') return false;
  if (typeof d.color_count !== 'number' || !Array.isArray(d.colors)) return false;
  for (const c of d.colors as unknown[]) {
    if (!c || typeof c !== 'object') return false;
    const cv = c as Record<string, unknown>;
    if (typeof cv.r !== 'number' || typeof cv.g !== 'number' || typeof cv.b !== 'number') return false;
  }
  return (d.colors as unknown[]).length === d.color_count;
}

function* walkJsonFiles(dir: string, recursive = true): Generator<string> {
  if (!fs.existsSync(dir)) return;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const ent of entries) {
    const full = path.join(dir, ent.name);
    if (ent.isDirectory() && recursive) {
      yield* walkJsonFiles(full, true);
    } else if (ent.isFile() && ent.name.toLowerCase().endsWith('.json')) {
      yield full;
    }
  }
}

ipcMain.handle('load-legacy-palettes', async () => {
  const dir = getLegacyPaletteDir();
  if (!dir) return [];
  const result: ProcessedPalette[] = [];
  for (const filePath of walkJsonFiles(dir)) {
    try {
      const raw = fs.readFileSync(filePath, 'utf-8');
      const data = JSON.parse(raw) as unknown;
      if (isValidPaletteData(data)) {
        result.push(processPaletteData(data));
      }
    } catch {
      // Skip invalid or unreadable files
    }
  }
  return result;
});

function ensureCategoryDir(baseDir: string, category: string): string {
  const safe = category.replace(/[<>:"/\\|?*]/g, '_').trim() || 'Uncategorized';
  const dir = path.join(baseDir, safe);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  return dir;
}

ipcMain.handle('save-palette-to-legacy', async (event, data: PaletteData) => {
  const dir = getLegacyPaletteDir();
  if (!dir) return { success: false, error: 'Legacy palette path not available on this platform' };
  if (!isValidPaletteData(data)) return { success: false, error: 'Invalid palette data' };
  try {
    const categoryDir = ensureCategoryDir(dir, data.category);
    const safeName = (data.name || 'Unnamed').replace(/[<>:"/\\|?*]/g, '_').trim() || 'Unnamed';
    const filePath = path.join(categoryDir, `${safeName}.json`);
    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
    return { success: true };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
  }
});

function processPaletteFile(filePath: string): { saved?: ProcessedPalette; failed?: string } {
  try {
    const raw = fs.readFileSync(filePath, 'utf-8');
    const data = JSON.parse(raw) as unknown;
    if (!isValidPaletteData(data)) return { failed: 'Invalid palette format' };
    const dir = getLegacyPaletteDir();
    if (!dir) return { failed: 'Legacy path not available' };
    const categoryDir = ensureCategoryDir(dir, data.category);
    const safeName = (data.name || path.basename(filePath, '.json')).replace(/[<>:"/\\|?*]/g, '_').trim() || 'Unnamed';
    const destPath = path.join(categoryDir, `${safeName}.json`);
    fs.writeFileSync(destPath, JSON.stringify(data, null, 2), 'utf-8');
    return { saved: processPaletteData(data) };
  } catch (error) {
    return { failed: error instanceof Error ? error.message : 'Unknown error' };
  }
}

ipcMain.handle('bulk-import-palettes-from-folder', async (event, folderPath: string, recursive: boolean) => {
  const saved: ProcessedPalette[] = [];
  const failed: { path: string; error: string }[] = [];
  for (const filePath of walkJsonFiles(folderPath, recursive)) {
    const result = processPaletteFile(filePath);
    if (result.saved) saved.push(result.saved);
    else if (result.failed) failed.push({ path: filePath, error: result.failed });
  }
  return { saved, failed };
});

ipcMain.handle('bulk-import-palettes-from-zip', async (event, zipPath: string, recursive: boolean) => {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const AdmZip = require('adm-zip');
  const tempDir = path.join(os.tmpdir(), `dither-boy-palettes-${Date.now()}`);
  const saved: ProcessedPalette[] = [];
  const failed: { path: string; error: string }[] = [];
  try {
    const tempDirResolved = path.resolve(tempDir);
    fs.mkdirSync(tempDir, { recursive: true });
    const zip = new AdmZip(zipPath);
    const entries = zip.getEntries();
    for (const entry of entries) {
      if (entry.isDirectory) continue;
      const entryName = entry.entryName.replace(/\\/g, '/');
      const destPath = path.join(tempDir, entryName);
      const destResolved = path.resolve(destPath);
      const relative = path.relative(tempDirResolved, destResolved);
      if (relative.startsWith('..') || path.isAbsolute(relative)) continue;
      fs.mkdirSync(path.dirname(destPath), { recursive: true });
      fs.writeFileSync(destPath, entry.getData());
    }
    for (const filePath of walkJsonFiles(tempDir, recursive)) {
      const result = processPaletteFile(filePath);
      if (result.saved) saved.push(result.saved);
      else if (result.failed) failed.push({ path: path.relative(tempDir, filePath), error: result.failed });
    }
  } finally {
    try {
      fs.rmSync(tempDir, { recursive: true, force: true });
    } catch {
      // Ignore cleanup errors
    }
  }
  return { saved, failed };
});

// IPC handlers for clipboard
ipcMain.handle('clipboard:readImage', async () => {
  try {
    const { clipboard, nativeImage } = require('electron');
    const image = clipboard.readImage();
    
    if (image.isEmpty()) {
      // Check for file paths (Windows Explorer)
      // Try to read file path - Windows uses UTF-16LE encoding
      let filePathRaw = clipboard.read('FileNameW');
      
      if (filePathRaw) {
        // FileNameW returns UTF-16LE encoded string
        // Convert the raw string to a buffer, treating each char as a byte
        const bytes: number[] = [];
        for (let i = 0; i < filePathRaw.length; i++) {
          bytes.push(filePathRaw.charCodeAt(i) & 0xFF);
        }
        
        // Create buffer from bytes and decode as UTF-16LE
        const buffer = Buffer.from(bytes);
        let filePath = buffer.toString('utf16le');
        
        // Remove null terminator at the end
        filePath = filePath.replace(/\0+$/g, '');
        
        // Validate file exists
        if (fs.existsSync(filePath)) {
          return { success: true, type: 'filepath', data: filePath };
        }
      }
      
      return { success: false, error: 'No image or file in clipboard' };
    }
    
    // Convert image to PNG buffer and return as base64
    const buffer = image.toPNG();
    const base64 = buffer.toString('base64');
    return { success: true, type: 'image', data: `data:image/png;base64,${base64}` };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
  }
});

ipcMain.handle('clipboard:writeImage', async (event, dataUrl: string) => {
  try {
    const { clipboard, nativeImage } = require('electron');
    const matches = dataUrl.match(/^data:image\/[a-z]+;base64,(.+)$/);
    if (!matches) {
      return { success: false, error: 'Invalid data URL format' };
    }
    const base64Data = matches[1];
    const buffer = Buffer.from(base64Data, 'base64');
    const image = nativeImage.createFromBuffer(buffer);
    clipboard.writeImage(image);
    return { success: true };
  } catch (error) {
    return { success: false, error: error instanceof Error ? error.message : 'Unknown error' };
  }
});

