// ─── Native FFmpeg management ────────────────────────────────────────────────

const FFMPEG_DIR_NAME = 'ffmpeg';

function getFFmpegBinaryPath(): string {
  const base = getAppDataDir();
  if (!base) return '';
  const bin = process.platform === 'win32' ? 'ffmpeg.exe' : 'ffmpeg';
  return path.join(base, FFMPEG_DIR_NAME, bin);
}

/** Download URL per platform. macOS uses x64 static build (runs via Rosetta on ARM). */
function getFFmpegDownloadUrl(): string | null {
  if (process.platform === 'win32') {
    return 'https://github.com/BtbN/FFmpeg-Builds/releases/download/latest/ffmpeg-master-latest-win64-gpl.zip';
  }
  if (process.platform === 'darwin') {
    return 'https://evermeet.cx/ffmpeg/getrelease/ffmpeg/zip';
  }
  return null;
}

/** Recursively find a file by name inside a directory. */
function findFileRecursive(dir: string, name: string): string | null {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      const found = findFileRecursive(full, name);
      if (found) return found;
    } else if (entry.name === name) {
      return full;
    }
  }
  return null;
}

/**
 * Extract the ffmpeg binary from the downloaded ZIP into destDir.
 * Uses child processes (PowerShell on Windows, unzip on macOS) so the
 * main process event loop is never blocked.
 */
async function extractFFmpegFromZip(zipPath: string, destDir: string): Promise<void> {
  const { spawn } = require('child_process');
  fs.mkdirSync(destDir, { recursive: true });
  const binName = process.platform === 'win32' ? 'ffmpeg.exe' : 'ffmpeg';

  if (process.platform === 'win32') {
    // Extract into a temp dir, then pick out ffmpeg.exe
    // (BtbN ZIPs nest it under e.g. ffmpeg-master-latest-win64-gpl/bin/)
    const tempExtract = path.join(os.tmpdir(), `dither-boy-extract-${Date.now()}`);
    try {
      await new Promise<void>((resolve, reject) => {
        const ps = spawn('powershell.exe', [
          '-NoProfile', '-NonInteractive', '-Command',
          `Expand-Archive -LiteralPath '${zipPath}' -DestinationPath '${tempExtract}' -Force`,
        ], { windowsHide: true });
        ps.on('close', (code: number) => code === 0 ? resolve() : reject(new Error(`Extraction failed (PowerShell exit ${code})`)));
        ps.on('error', reject);
      });

      const found = findFileRecursive(tempExtract, binName);
      if (!found) throw new Error('ffmpeg.exe not found inside downloaded ZIP');
      fs.copyFileSync(found, path.join(destDir, binName));
    } finally {
      try { fs.rmSync(tempExtract, { recursive: true, force: true }); } catch { /* ignore */ }
    }
  } else {
    // macOS: evermeet.cx ZIPs have ffmpeg at the root - extract just that entry
    await new Promise<void>((resolve, reject) => {
      const proc = spawn('unzip', ['-o', zipPath, binName, '-d', destDir]);
      proc.on('close', (code: number) => code === 0 ? resolve() : reject(new Error(`Extraction failed (unzip exit ${code})`)));
      proc.on('error', reject);
    });
    fs.chmodSync(path.join(destDir, binName), 0o755);
  }
}

/** Probe the version string from our private binary (non-blocking). */
function probeFFmpegVersion(binPath: string): Promise<string | null> {
  return new Promise((resolve) => {
    const { execFile } = require('child_process');
    execFile(binPath, ['-version'], { timeout: 8000 }, (err: any, stdout: string, stderr: string) => {
      if (err) { resolve(null); return; }
      const out = stdout || stderr;
      const match = out.match(/ffmpeg version (\S+)/);
      resolve(match ? match[1] : 'unknown');
    });
  });
}

ipcMain.handle('ffmpeg:getStatus', async () => {
  const binPath = getFFmpegBinaryPath();
  if (!binPath || !fs.existsSync(binPath)) {
    return { installed: false, path: null, version: null };
  }
  const version = await probeFFmpegVersion(binPath);
  if (!version) {
    return { installed: false, path: null, version: null };
  }
  return { installed: true, path: binPath, version };
});

ipcMain.handle('ffmpeg:download', async (event) => {
  const send = (data: object) => {
    try { event.sender.send('ffmpeg:download-progress', data); } catch { /* window closed */ }
  };

  const url = getFFmpegDownloadUrl();
  if (!url) {
    return { success: false, error: 'No FFmpeg download available for this platform.' };
  }

  const base = getAppDataDir();
  if (!base) {
    return { success: false, error: 'Cannot determine app data directory.' };
  }

  const tmpZip = path.join(os.tmpdir(), `dither-boy-ffmpeg-${Date.now()}.zip`);
  const destDir = path.join(base, FFMPEG_DIR_NAME);

  try {
    // ── Download ──────────────────────────────────────────────────────────
    send({ phase: 'downloading', percent: 0, message: 'Starting download…' });

    await new Promise<void>((resolve, reject) => {
      const https = require('https');
      const file = fs.createWriteStream(tmpZip);

      const doRequest = (requestUrl: string, redirectCount = 0) => {
        if (redirectCount > 5) { reject(new Error('Too many redirects')); return; }
        https.get(requestUrl, (res: any) => {
          if (res.statusCode === 301 || res.statusCode === 302) {
            res.resume(); // drain so the socket is released before next request
            doRequest(res.headers.location, redirectCount + 1);
            return;
          }
          if (res.statusCode !== 200) {
            reject(new Error(`HTTP ${res.statusCode}`));
            return;
          }
          const total = parseInt(res.headers['content-length'] || '0', 10);
          let downloaded = 0;
          res.on('data', (chunk: Buffer) => {
            downloaded += chunk.length;
            file.write(chunk);
            if (total > 0) {
              send({ phase: 'downloading', percent: Math.round((downloaded / total) * 85), message: `Downloading… ${Math.round(downloaded / 1024 / 1024)} MB` });
            }
          });
          res.on('end', () => { file.end(() => resolve()); });
          res.on('error', (err: Error) => { file.destroy(); reject(err); });
        }).on('error', reject);
      };

      doRequest(url);
    });

    // ── Extract ───────────────────────────────────────────────────────────
    send({ phase: 'extracting', percent: 87, message: 'Extracting…' });
    await extractFFmpegFromZip(tmpZip, destDir);

    // ── macOS Gatekeeper quarantine removal ───────────────────────────────
    const binPath = getFFmpegBinaryPath();
    if (process.platform === 'darwin') {
      send({ phase: 'installing', percent: 93, message: 'Removing quarantine…' });
      try {
        const { execSync } = require('child_process');
        execSync(`xattr -d com.apple.quarantine "${binPath}"`, { timeout: 5000 });
      } catch {
        // Attribute may not exist - not an error
      }
    }

    // ── Verify ────────────────────────────────────────────────────────────
    send({ phase: 'verifying', percent: 97, message: 'Verifying…' });
    const version = await probeFFmpegVersion(binPath);
    if (!version) {
      throw new Error('Downloaded binary failed verification.');
    }

    send({ phase: 'done', percent: 100, message: `Installed FFmpeg ${version}` });
    return { success: true, version };
  } catch (error) {
    const msg = error instanceof Error ? error.message : String(error);
    send({ phase: 'error', percent: 0, message: msg });
    return { success: false, error: msg };
  } finally {
    try { fs.unlinkSync(tmpZip); } catch { /* ignore */ }
  }
});

