ipcMain.handle('ffmpeg:execNative', async (event, args: string[]) => {
  const binPath = getFFmpegBinaryPath();
  if (!binPath || !fs.existsSync(binPath)) {
    return { exitCode: 1, logs: ['FFmpeg binary not found'] };
  }

  const send = (data: object) => {
    try { event.sender.send('ffmpeg:exec-progress', data); } catch { /* window closed */ }
  };

  const { spawn } = require('child_process');
  const logs: string[] = [];

  return new Promise<{ exitCode: number; logs: string[] }>((resolve) => {
    const proc = spawn(binPath, args, { stdio: ['ignore', 'pipe', 'pipe'] });

    const onData = (data: Buffer) => {
      const line = data.toString();
      logs.push(line);
      // Parse FFmpeg progress line: frame=X fps=Y ...
      const frameMatch = line.match(/frame=\s*(\d+)/);
      const fpsMatch = line.match(/fps=\s*([\d.]+)/);
      const timeMatch = line.match(/time=(\d+:\d+:\d+\.\d+)/);
      if (frameMatch || timeMatch) {
        send({
          frame: frameMatch ? parseInt(frameMatch[1], 10) : null,
          fps: fpsMatch ? parseFloat(fpsMatch[1]) : null,
          time: timeMatch ? timeMatch[1] : null,
        });
      }
    };

    proc.stdout.on('data', onData);
    proc.stderr.on('data', onData);
    proc.on('close', (code: number) => resolve({ exitCode: code ?? 1, logs }));
    proc.on('error', (err: Error) => {
      logs.push(err.message);
      resolve({ exitCode: 1, logs });
    });
  });
});

