ipcMain.on('open-external', async (event, url: string) => {
  try {
    // Only allow https URLs for security
    if (url.startsWith('https://')) {
      const { shell } = require('electron');
      await shell.openExternal(url);
    }
  } catch (error) {
    console.error('Failed to open external URL:', error);
  }
});

// IPC handler for getting log count
ipcMain.handle('get-log-count', async () => {
  try {
    const logsDir = getLogsDir();
    if (!logsDir) {
      return { success: false, count: 0 };
    }
    
    // Check if directory exists
    if (!fs.existsSync(logsDir)) {
      return { success: true, count: 0 };
    }
    
    // Count .log files in the directory
    const files = fs.readdirSync(logsDir);
    const logFiles = files.filter(file => file.endsWith('.log'));
    
    return { success: true, count: logFiles.length };
  } catch (error) {
    console.error('Failed to get log count:', error);
    return { success: false, count: 0 };
  }
});

// IPC handler for opening logs folder
ipcMain.handle('open-logs-folder', async () => {
  try {
    const logsDir = getLogsDir();
    if (!logsDir) {
      return { success: false, error: 'Logs directory not available on this platform' };
    }
    
    // Create the directory if it doesn't exist
    if (!fs.existsSync(logsDir)) {
      fs.mkdirSync(logsDir, { recursive: true });
    }
    
    const { shell } = require('electron');
    await shell.openPath(logsDir);
    return { success: true };
  } catch (error) {
    console.error('Failed to open logs folder:', error);
    return { 
      success: false, 
      error: error instanceof Error ? error.message : 'Unknown error' 
    };
  }
});

app.whenReady().then(async () => {
  session.defaultSession.setPermissionRequestHandler((_webContents, _permission, callback) => callback(false));

  // Purge stale dither-boy-export-* temp dirs from previous sessions in the
  // background - fully async so slow disks never delay the app opening.
  fs.promises.readdir(os.tmpdir(), { withFileTypes: true })
    .then(entries => Promise.allSettled(
      entries
        .filter(e => e.isDirectory() && e.name.startsWith('dither-boy-export-'))
        .map(e => fs.promises.rm(path.join(os.tmpdir(), e.name), { recursive: true, force: true }))
    ))
    .catch(() => { /* non-fatal */ });

  // Serve frame PNGs from the OS temp directory directly to the renderer.
  // The file path comes from the `p` query parameter (percent-encoded) to avoid
  // Windows drive-letter ambiguity in URL path parsing (e.g. C: treated as host).
  protocol.handle('app-frame', async (request) => {
    try {
      const url = new URL(request.url);
      const filePath = url.searchParams.get('p') || '';
      if (!filePath) return new Response('Bad Request', { status: 400 });
      const data = await fs.promises.readFile(filePath);
      return new Response(data, { status: 200, headers: { 'Content-Type': 'image/png' } });
    } catch {
      return new Response('Not Found', { status: 404 });
    }
  });

  initSessionLog();
  
  // Load license manager from bytecode
  try {
    loadLicenseManager();

    // Initialize license manager (loads and verifies stored license)
    await licenseManager.initialize();
  } catch (error) {
    console.error('[App] CRITICAL: Failed to load license manager:', error);

    dialog.showErrorBox(
      'Application Error',
      `Failed to initialize application.\n\n` +
      `Please reinstall the application or contact support@studioaaa.com`
    );
    app.quit();
    return;
  }

  // Load halftone processor from bytecode
  loadHalftoneProcessor();
  
  createWindow();
  
  // Initialize Discord Rich Presence
  discordPresence = new DiscordPresence({
    clientId: DISCORD_CLIENT_ID,
    appName: APP_NAME,
    appVersion: APP_VERSION,
    appDeveloper: APP_DEVELOPER,
    largeImageKey: DISCORD_LARGE_IMAGE_KEY,
    websiteUrl: DISCORD_WEBSITE_URL,
    developerUrl: DISCORD_DEVELOPER_URL,
  });
  discordPresence.start('Idle');

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) {
      createWindow();
    }
  });
});

app.on('window-all-closed', () => {
  if (ditherWorker) {
    ditherWorker.terminate();
    ditherWorker = null;
  }
  if (logStream) {
    logStream.end();
    logStream = null;
  }
  if (discordPresence) {
    discordPresence.destroy();
    discordPresence = null;
  }
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

// Discord Presence IPC handlers
ipcMain.on('discord:start', (event, data: any) => {
  if (discordPresence) {
    discordPresence.start(data);
  }
});

ipcMain.on('discord:update', (event, data: any) => {
  if (discordPresence) {
    discordPresence.updatePresence(data);
  }
});

ipcMain.on('discord:updateStyle', (event, style: string) => {
  if (discordPresence) {
    discordPresence.updateStyle(style);
  }
});

ipcMain.on('discord:clear', () => {
  if (discordPresence) {
    discordPresence.clear();
  }
});

